<!doctype html><html><head><meta charset="utf-8"><title>Barcode and QR labels</title><style>body{font-family:Arial,sans-serif}.toolbar{margin:1rem}.labels{display:flex;flex-wrap:wrap;gap:12px}.label{width:260px;min-height:120px;border:1px dashed #777;padding:12px;text-align:center;box-sizing:border-box}.label svg{width:230px;height:60px}.label img{width:130px;height:130px;display:block;margin:8px auto}.label small{display:block;margin-top:4px}@media print{.toolbar{display:none}.label{break-inside:avoid}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print labels</button></div><div class="labels">@foreach($product->barcodes->where('type', 'barcode') as $barcode)@php($segments = app(\App\Services\BarcodeService::class)->code39($barcode->code))<div class="label"><strong>{{ $product->name }}</strong><svg viewBox="0 0 {{ collect($segments)->sum('width') }} 30" preserveAspectRatio="none" role="img" aria-label="{{ $barcode->code }}">@php($x = 0)@foreach($segments as $segment)@if($segment['bar'])<rect x="{{ $x }}" y="0" width="{{ $segment['width'] }}" height="30" fill="#000"/>@endif @php($x += $segment['width'] )@endforeach</svg><small>{{ $barcode->code }}{{ $barcode->is_primary ? ' (primary)' : '' }}</small></div>@endforeach @foreach($product->barcodes->where('type', 'qrcode') as $barcode)<div class="label"><strong>{{ $product->name }}</strong>@if($qrImages[$barcode->id] ?? null)<img src="{{ $qrImages[$barcode->id] }}" alt="QR code {{ $barcode->code }}">@else<p>QR encoder unavailable.</p>@endif<small>{{ $barcode->code }}{{ $barcode->is_primary ? ' (primary)' : '' }}</small></div>@endforeach</div>@if($product->barcodes->isEmpty())<p>No printable barcode or QR records found.</p>@endif</body></html>
